-- @case 1: search name: LIKE "a_"
BEGIN;
DELETE FROM application.people;
DELETE FROM sales.customers;
DELETE FROM purchasing.suppliers;
INSERT INTO application.people ("PersonID", "FullName", "PreferredName", "IsSalesperson", "IsEmployee", "SearchName") VALUES
  ('1', 'Q0001', 'Q', '0', '1', 'a_b'),
  ('2', 'Q0002', 'Q', '0', '0', 'xay'),
  ('3', 'Q0003', 'Q', '0', '1', 'a'),
  ('4', 'Q0004', 'Q', '0', '0', 'A-');
DO $pp$
DECLARE got jsonb;
BEGIN
  SELECT (q.result)::jsonb INTO got FROM (SELECT website.search_for_people('a_'::text, '5'::integer) AS result) AS q;
  IF got IS DISTINCT FROM '{"People":[{"PersonID":1,"FullName":"Q0001","PreferredName":"Q","Relationship":"Employee","Company":"WWI"},{"PersonID":2,"FullName":"Q0002","PreferredName":"Q","Company":"WWI"},{"PersonID":4,"FullName":"Q0004","PreferredName":"Q","Company":"WWI"}]}'::jsonb THEN
    RAISE EXCEPTION 'agreed test failed (%): the JSON document differs: %', 'test 01 search name: LIKE a_', got;
  END IF;
END $pp$;
ROLLBACK;

